content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "County",
      "description": "An area with a governance",
      "attributes": "General Information"
    },
    {
      "name": "General Information",
      "description": "General Information about the county accessible to the public"
    },
    {
      "name": "County Resident",
      "description": "resident of the county who can access information and the services provided by the county"
    },
    {
      "name": "County Staff Member",
      "description": "staff member of a county, who processes applications and is in contact with applicants"
    },
    {
      "name": "Supervising Staff Member",
      "description": "orchestrates activity of other staff members"
    },
    {
      "name": "Resident Request",
      "description": "a request submitted by a resident to the county"
    },
    {
      "name": "Ordinance",
      "description": "regulations and laws enforced by the county"
    },
    {
      "name": "Application",
      "description": "submitted by an applicant to initiate transaction with the county",
      "attributes": "Supporting Documentation, Transaction Status, Proffer"
    },
    {
      "name": "Supporting Documentation",
      "description": "the documentation required for a certain application to be provided by the applicant"
    },
    {
      "name": "County Service",
      "description": "a service offered by the county"
    },
    {
      "name": "Transaction Status",
      "description": "information about the state of the process"
    },
    {
      "name": "Internal Note",
      "description": "information about a record that is shared between staff members"
    },
    {
      "name": "Completeness Review",
      "description": "performed by a staff member to ensure an application is complete and eligible for technical review"
    },
    {
      "name": "Detailed Review",
      "description": "application is reviewed for compliance and subsequently approved or denied"
    },
    {
      "name": "Plan Set",
      "description": "concrete construction site plans"
    },
    {
      "name": "Plan Review",
      "description": "conducted to ensure the plans align with the comprehensive plan"
    },
    {
      "name": "Proffer",
      "description": "conditional offers by the applicant",
      "attributes": "Proffer State"
    },
    {
      "name": "Proffer State",
      "description": "Proffers can be in draft or approved state"
    },
    {
      "name": "Staff Review",
      "description": "conducted to ensure that the application is compliant with the zoning ordinance"
    },
    {
      "name": "Zoning Permit",
      "description": "can be issued if the request is compliant with the zoning ordinance"
    },
    {
      "name": "Development Permit",
      "description": "can be issued to grant the request to begin work"
    },
    {
      "name": "Staff Report",
      "description": "an evaluation overview of the application"
    },
    {
      "name": "Bond",
      "description": "sum provided by the applicant before starting work"
    },
    {
      "name": "Building Development Status",
      "description": "displays whether work is finished"
    },
    {
      "name": "Inspection",
      "description": "conducted by an Inspector to validate compliance with code and regulations"
    },
    {
      "name": "Formal Response",
      "description": "sent to resident by a staff member to satisfy communication and records responsibilities"
    },
    {
      "name": "County Issue",
      "description": "a matter relevant to the county which is to be resolved"
    },
    {
      "name": "Scheduled Meeting",
      "description": "all stakeholders come together to address an issue",
      "attributes": "Meeting Time"
    },
    {
      "name": "Meeting Time",
      "description": "the specific time/date that the meeting is held"
    },
    {
      "name": "Stakeholder",
      "description": "a party that is relevant to an issue"
    },
    {
      "name": "Plan Review Meeting",
      "description": "held between the applicant and the plan review staff"
    },
    {
      "name": "Hearing",
      "description": "a meeting where a board decides on an application",
      "attributes": "Hearing Date, Governing Body, Hearing Decision, Affidavit"
    },
    {
      "name": "Hearing Date",
      "description": "the date of the hearing"
    },
    {
      "name": "Governing Body",
      "description": "the body responsible for the issue"
    },
    {
      "name": "Affidavit",
      "description": "a sworn statement of fact, required as proof that certain requirements are met"
    },
    {
      "name": "Hearing Decision",
      "description": "whether an application is to be approved or not"
    },
    {
      "name": "County Rules",
      "description": "dictate the procedures and business laws of the county",
      "attributes": "Comprehensive Plan, Zoning Information, Ordinance"
    },
    {
      "name": "Comprehensive Plan",
      "description": "policy document that contains the documentation of the development of the county"
    },
    {
      "name": "Plan Report",
      "description": "a document containing all the relevant information of a plan"
    },
    {
      "name": "Zoning Information",
      "description": "relevant data about zoning"
    },
    {
      "name": "Violation Notice",
      "description": "issued when a violation against county policies is noticed by an enforcer"
    },
    {
      "name": "GIS (Geographic Information System)",
      "description": "the County's computer system for capturing, storing, and displaying data related to geographic positions (for technical members)"
    },
    {
      "name": "Geospatial Data",
      "description": "relevant to reviews"
    },
    {
      "name": "Parcel",
      "description": "a unit of land or real estate",
      "attributes": "Parcel Pin, Property History"
    },
    {
      "name": "Property History",
      "description": "contains all relevant past information to the property"
    },
    {
      "name": "ParcelPIN",
      "description": "A unique number assigned to a parcel for tracking and record-keeping"
    },
    {
      "name": "Citation-Post",
      "description": "Information in form of a notice of violation to be sent to the affected property owner"
    },
    {
      "name": "Project",
      "description": "an endeavor by a resident for construction or such",
      "attributes": "County Service, Bond, Plan Set, Building Development Status"
    }
  ]
}
```
